import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static class Node {
        long key;
        int priority;
        int count;
        int size;
        Node left, right;

        Node(long key, int priority) {
            this.key = key;
            this.priority = priority;
            this.count = 1;
            this.size = 1;
        }
    }

    static Node root;
    static int randomState = 0x6D2B79F5;

    static int nextRandom() {
        randomState ^= randomState << 13;
        randomState ^= randomState >>> 17;
        randomState ^= randomState << 5;
        return randomState;
    }

    static int size(Node node) {
        return node == null ? 0 : node.size;
    }

    static void update(Node node) {
        node.size = node.count + size(node.left) + size(node.right);
    }

    static Node rotateRight(Node node) {
        Node result = node.left;
        node.left = result.right;
        result.right = node;
        update(node);
        update(result);
        return result;
    }

    static Node rotateLeft(Node node) {
        Node result = node.right;
        node.right = result.left;
        result.left = node;
        update(node);
        update(result);
        return result;
    }

    static Node insert(Node node, long key) {
        if (node == null) return new Node(key, nextRandom());

        if (key == node.key) {
            node.count++;
        } else if (key < node.key) {
            node.left = insert(node.left, key);
            if (Integer.compareUnsigned(node.left.priority, node.priority) > 0) {
                node = rotateRight(node);
            }
        } else {
            node.right = insert(node.right, key);
            if (Integer.compareUnsigned(node.right.priority, node.priority) > 0) {
                node = rotateLeft(node);
            }
        }

        update(node);
        return node;
    }

    static int countLessThanOrEqual(long key) {
        int result = 0;
        Node node = root;

        while (node != null) {
            if (key < node.key) {
                node = node.left;
            } else {
                result += size(node.left) + node.count;
                node = node.right;
            }
        }

        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        StringBuilder output = new StringBuilder();

        int previousPenalty = 0;
        for (int i = 0; i < n; i++) {
            long x = (long) scanner.nextInt() + previousPenalty;
            long y = (long) scanner.nextInt() + previousPenalty;
            long distanceSquared = x * x + y * y;

            int penalty = countLessThanOrEqual(distanceSquared);
            output.append(penalty).append('\n');

            root = insert(root, distanceSquared);
            previousPenalty = penalty;
        }

        System.out.print(output);
    }
}
